def longest_run(nums):
    have = set(nums)
    best = 0
    for x in have:
        if x - 1 not in have:
            y = x
            while y + 1 in have:
                y += 1
            best = max(best, y - x + 1)
    return best

items.prompt:
An end-of-day job checks that every trade id in the exchange's file is in our booking system, and reports booked ids that appear more than once.

```python
def reconcile(exchange_ids, booked_ids):
    missing = []
    dupes = []
    for t in exchange_ids:
        if t not in booked_ids:
            missing.append(t)
    for i in range(len(booked_ids)):
        for j in range(i + 1, len(booked_ids)):
            if booked_ids[i] == booked_ids[j]:
                dupes.append(booked_ids[i])
    return missing, dupes
```

